var n=`0724-poulet-nyembwe`;var i=`world-0724`;var a=`GA`;var s=`central-africa`;var o=4;var r=66;var l={en:`Poulet Nyembwe`,ua:`Курка ньємбве`};var g={en:`Poulet Nyembwe is a Gabon classic prepared with chicken thigh, yellow onion, palm nut concentrate, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Курка ньємбве, страва кухні країни Габон зі складниками: куряче стегно, жовта цибуля, концентрат пальмових плодів, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,830,`g`],[`red-palm-oil`,55,`ml`],[`yellow-onion`,190,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`palm-nut-concentrate`,235,`g`],[`water`,750,`ml`],[`tomato`,320,`g`],[`garlic`,4,`clove`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`],[`table-salt`,null,`to_taste`]]}];var m={slug:n,id:i,country:`GA`,region:s,servings:4,minutes:66,title:l,text:g,steps:h};export{a as country,m as default,i as id,r as minutes,s as region,o as servings,n as slug,h as steps,g as text,l as title};